globalThis.MediaInfoProjectMedia = {"tutorial":{"title":"Erklär’s besser","tag":"Eine Anleitung, die wirklich hilft","duration":100,"chapters":[{"title":"Ein Problem. Ein klarer Weg.","kind":"cards","seconds":12,"caption":"Eine gute Anleitung zeigt Ziel, Handlung und sichtbares Ergebnis. Beschränken Sie sich auf eine Funktion.","cards":[["Ziel","Einen Bildausschnitt in die eigene Anleitung einfügen."],["Handlung","Das passende Werkzeug öffnen und den Ausschnitt wählen."],["Ergebnis","Das Bild ist eingefügt und die wichtige Stelle lesbar."]],"why":"Die Person weiss vor dem Start, was sie am Schluss können wird.","start":0,"image":"tutorial-01.svg"},{"title":"Beispiel 1 · Der Screenshot","kind":"browser","seconds":16,"caption":"Vergrössern Sie die wichtige Stelle. Nummer, klare Anweisung und Bild gehören zusammen. Der dargestellte Bildschirm ist ein Beispielaufbau.","cards":[["1 · Ansicht vorbereiten","Nur das benötigte Fenster zeigen."],["2 · Ausschnitt wählen","Die wichtige Schaltfläche vollständig erfassen."],["3 · Bild erklären","«Wählen Sie Speichern. Danach liegt die Datei im Projektordner.»"]],"why":"Ein enger Bildausschnitt macht die Entscheidung sichtbar.","start":12,"image":"tutorial-02.svg"},{"title":"Beispiel 2 · Eine Datei wiederfinden","kind":"path","seconds":16,"caption":"Ein konkreter Speicherweg und ein geprüfter Dateiname verhindern Sucherei. Testen Sie den Weg nach dem Schliessen der Datei.","cards":[["Ordner","OneDrive / Informatik / Projekte / Tutorial"],["Name","Tutorial-Screenshot-Vorname.pdf"],["Probe","Datei schliessen → Ordner öffnen → richtige Datei öffnen"]],"why":"Der Test beweist, dass der Ablauf bis zum Ergebnis funktioniert.","start":28,"image":"tutorial-03.svg"},{"title":"Beispiel 3 · Ein nützlicher Link","kind":"compare","seconds":16,"caption":"Ein Link braucht einen verständlichen Namen und ein geprüftes Ziel. Beim Test soll die andere Person ohne zusätzliche Erklärung weiterkommen.","cards":[["Unklar","«Hier klicken»\nWohin führt das?"],["Hilfreich","«Meine Informatik-Aufträge»\nLink geöffnet, Ziel kontrolliert."],["Ohne-Hilfe-Test","Die Person findet den richtigen Auftrag selbst."]],"why":"Gute Bezeichnungen ersetzen zusätzliche Erklärungen.","start":44,"image":"tutorial-04.svg"},{"title":"So planen Sie ein 75-Sekunden-Video","kind":"timeline","seconds":14,"caption":"Planen Sie zuerst den Ablauf: 10 Sekunden Ziel, 50 Sekunden sichtbare Arbeit und 15 Sekunden Ergebnis. Nehmen Sie vorab eine kurze Probe auf.","cards":[["0–10 s · Ziel","Was kann ich danach?"],["10–60 s · Ablauf","Kleine Schritte, gut lesbar, kurze Pausen."],["60–75 s · Kontrolle","Das Ergebnis zeigen und den Erfolg prüfen."]],"why":"Ein Zeitplan lässt Raum für die wichtige Schlusskontrolle.","start":60,"image":"tutorial-05.svg"},{"title":"Vom Zögern zur Verbesserung","kind":"compare","seconds":14,"caption":"Beobachten Sie beim Test. Wenn jemand zögert, ergänzen Sie genau die fehlende Information und testen Sie erneut.","cards":[["Beobachtung","Die Testperson weiss nicht, welches Symbol gemeint ist."],["Verbesserung","Bild enger zuschneiden. Symbol markieren. Namen ergänzen."],["Erneuter Test","Die Person findet das Symbol ohne Hinweis."]],"why":"Eine konkrete Verbesserung zeigt, was Sie gelernt haben.","start":74,"image":"tutorial-06.svg"},{"title":"Jetzt Ihre eigene Fassung","kind":"cards","seconds":12,"caption":"Wählen Sie eine Vorlage in der Werkbank. Schreiben Sie Ihr Ziel. Planen Sie mindestens fünf sinnvolle Schritte. Verwenden Sie eigene Bilder oder Ihre eigene Aufnahme.","cards":[["01 · Vorlage","Screenshot, Datei wiederfinden oder eigene Idee."],["02 · Material","Mindestens fünf eigene Bilder oder ein 60–90-Sekunden-Video."],["03 · Test","Ohne Hilfe ausprobieren lassen und gezielt verbessern."]],"why":"Beginnen Sie mit einem kleinen Problem, das Ihre Klasse kennt.","start":88,"image":"tutorial-07.svg"}]},"cockpit":{"title":"Mein digitales Cockpit","tag":"Weniger suchen. Klarer beginnen.","duration":100,"chapters":[{"title":"Vier Bereiche. Ein schneller Einstieg.","kind":"board","seconds":12,"caption":"Ein Cockpit beantwortet vier Fragen: Was tue ich zuerst? Was steht an? Wo arbeite ich? Was will ich erreichen?","cards":[["Aufgaben","Zuerst: Scan prüfen und als PDF speichern."],["Termine","Abgabe und Vorbereitung unterscheiden."],["Links","Direkt zu Aufträgen und Arbeitsdateien."],["Ziel","Ein erreichbares Ergebnis für diese Woche."]],"why":"Alle Bereiche helfen bei einer konkreten Entscheidung.","start":0,"image":"cockpit-01.svg"},{"title":"Beispiel 1 · Schule im Griff","kind":"board","seconds":16,"caption":"Dieses Schulbeispiel enthält drei Aufgaben, zwei erfundene Termine, drei Linknamen und ein Ziel. Übernehmen Sie echte Termine nur aus Ihrer Quelle.","cards":[["Meine Aufgaben","ZUERST · Scan öffnen und prüfen\nTutorial-Bilder ergänzen\nQuellenlinks kontrollieren"],["Termine · Übung","Dienstag, 10:00 · Zwischentest\nFreitag, 12:00 · Ergebnis zeigen"],["Meine Links","Informatik-Aufträge\nMein Projektordner\nMein OneNote-Notizbuch"],["Mein Ziel","Bis Freitag: Tutorial so verbessern, dass der Ablauf ohne Hilfe gelingt."]],"why":"Ein Verb und ein sichtbares Ergebnis machen Aufgaben ausführbar.","start":12,"image":"cockpit-02.svg"},{"title":"Beispiel 2 · Schnupperlehre","kind":"board","seconds":16,"caption":"Die gleiche Struktur hilft bei einer anderen Situation. Dieses Beispiel ist erfunden und enthält keine fremden Kontaktdaten.","cards":[["Vorbereiten","3 Fragen zum Beruf notieren\nAnreise prüfen\nBenötigte Unterlagen ordnen"],["Termine · Übung","Montag · Vorbereitung prüfen\nMittwoch · Schnuppertag"],["Schnellzugriffe","Meine Fragen\nMeine Packliste\nÖffentlicher Fahrplan"],["Nächstes Ziel","Am Vortag liegen Fragen und benötigte Unterlagen bereit."]],"why":"Sie passen die Inhalte an Ihren Alltag an, die Orientierung bleibt.","start":28,"image":"cockpit-03.svg"},{"title":"Beispiel 3 · Meine Lernwoche","kind":"board","seconds":16,"caption":"Ein Wochenplan wird nützlich, wenn grosse Vorhaben in kleine nächste Handlungen zerlegt sind. Die Termine hier sind Übungsangaben.","cards":[["Diese Woche","5 Begriffe mit Beispielen notieren\nPDF auf 3 Angaben prüfen\nEine offene Frage klären"],["Termine · Übung","Dienstag · Selbsttest\nDonnerstag · Fragen besprechen"],["Direkt öffnen","Lernnotizen\nÜbungsdossier\nAufgabenübersicht"],["Mein Ziel","Die fünf Begriffe am Donnerstag ohne Nachschlagen erklären."]],"why":"Das Ziel lässt sich prüfen; der erste Schritt ist klein genug.","start":44,"image":"cockpit-04.svg"},{"title":"Von «lernen» zu einem Auftrag","kind":"compare","seconds":14,"caption":"Zu grosse oder vage Einträge blockieren den Start. Formulieren Sie eine sichtbare Handlung und nennen Sie bei Bedarf den ersten kleinen Schritt.","cards":[["Zu vage","«Informatik machen»\nWo soll ich anfangen?"],["Ausführbar","«Drei PDF-Seiten auf Lesbarkeit prüfen»"],["Erster Schritt","PDF am Notebook öffnen und auf Seite 1 zoomen."]],"why":"Eine klare Aufgabe senkt die Hürde, tatsächlich anzufangen.","start":60,"image":"cockpit-05.svg"},{"title":"Der 10-Sekunden-Test","kind":"cards","seconds":14,"caption":"Schliessen und öffnen Sie die OneNote-Seite. Finden Sie Aufgabe, Termin und Link jeweils in etwa zehn Sekunden. Das ist ein Testziel, keine Geschwindigkeitsnote.","cards":[["Nächste Aufgabe?","Das Wort ZUERST fällt direkt auf."],["Nächster Termin?","Datum und Anlass stehen zusammen."],["Benötigte Datei?","Der benannte Link führt zum richtigen Ort."]],"why":"Die langsamste Stelle zeigt Ihnen, was Sie verbessern sollten.","start":74,"image":"cockpit-06.svg"},{"title":"Jetzt Ihr persönliches Cockpit","kind":"path","seconds":12,"caption":"Wählen Sie eine Vorlage, füllen Sie die vier Bereiche und kopieren Sie den Entwurf nach OneNote. Dort setzen und testen Sie Links und echte Aufgaben-Kästchen.","cards":[["Werkbank","Inhalt entwerfen und verständlich benennen."],["OneNote","In den persönlichen Bereich übertragen und nutzbar machen."],["Alltag","Am Anfang ansehen, am Schluss aktualisieren."]],"why":"Ein Cockpit wird durch regelmässige Nutzung wertvoll.","start":88,"image":"cockpit-07.svg"}]},"dokumente":{"title":"Alles in einer PDF","tag":"Ein Dossier, das man wirklich benutzen kann","duration":100,"chapters":[{"title":"Drei Seiten. Eine brauchbare Datei.","kind":"pages","seconds":12,"caption":"Ein gutes Dossier verbindet drei zusammengehörige Seiten: sinnvoll geordnet, vollständig und gut lesbar in einer einzigen PDF.","cards":[["1 · Überblick","Worum geht es?"],["2 · Details","Was muss ich wissen?"],["3 · Checkliste","Was tue ich als Nächstes?"]],"why":"Denken Sie an die Person, die mit dem Dossier arbeiten wird.","start":0,"image":"dokumente-01.svg"},{"title":"Beispiel 1 · Open-Air Nord","kind":"pages","seconds":16,"caption":"Das bereitgestellte Übungsmaterial wird B, C, A geordnet: erst Tagesinfo, dann Anreise, zuletzt Packliste. Alle Angaben sind erfunden.","cards":[["1 · Tagesinfo · B","Beginn: 14:00\nWas erwartet mich?"],["2 · Anreise · C","Geplante Ankunft: 13:22\nWie komme ich hin?"],["3 · Packliste · A","Regenjacke einpacken\nWas nehme ich mit?"]],"why":"Die Reihenfolge folgt den Fragen der nutzenden Person.","start":12,"image":"dokumente-02.svg"},{"title":"Beispiel 2 · Lernunterlagen","kind":"pages","seconds":16,"caption":"Drei eigene Lernblätter können vom Überblick über ein durchgerechnetes Beispiel zur eigenen Übung führen. Die Reihenfolge folgt dem Lernweg.","cards":[["1 · Überblick","Begriffe und Regeln"],["2 · Beispiel","Ein vollständig erklärter Ablauf"],["3 · Übung","Eine Aufgabe zum selbstständigen Ausprobieren"]],"why":"Zusammengehörige Blätter bilden einen nachvollziehbaren Weg.","start":28,"image":"dokumente-03.svg"},{"title":"Beispiel 3 · Ein Vereinsanlass","kind":"pages","seconds":16,"caption":"Ein weiterer erfundener Aufbau: Programm, öffentlicher Lageplan und Materialliste. Verwenden Sie keine privaten Kontaktdaten.","cards":[["1 · Programm","Wann beginnt welcher Teil?"],["2 · Lageplan","Wo ist der Treffpunkt?"],["3 · Materialliste","Was muss ich mitbringen?"]],"why":"Wählen Sie nur drei Seiten, die dieselbe Situation unterstützen.","start":44,"image":"dokumente-04.svg"},{"title":"Lesbarkeit vor Schönheit","kind":"compare","seconds":14,"caption":"Dunkle Ränder, Schatten oder abgeschnittene Zeilen erschweren die Nutzung. Prüfen Sie jede Seite vergrössert und erfassen Sie schlechte Seiten neu.","cards":[["Problem","Rechter Rand fehlt.\nDie Uhrzeit ist abgeschnitten."],["Korrektur","Seite flach legen.\nGleichmässiges Licht.\nAlle Ränder im Bild."],["Kontrolle","Kleinste wichtige Angabe vergrössert lesen."]],"why":"Eine neue Aufnahme ist oft schneller als langes Reparieren.","start":60,"image":"dokumente-05.svg"},{"title":"Der Härtetest am Notebook","kind":"cards","seconds":14,"caption":"Öffnen Sie die exportierte PDF ausserhalb des Erstellungsprogramms. Prüfen Sie Seitenzahl und Ordnung, finden Sie drei Angaben und notieren Sie die Dateigrösse.","cards":[["Struktur","Genau 3 Seiten, aufrecht und in der geplanten Reihenfolge."],["Inhalt","Beginn, Ankunft und Regenausrüstung finden."],["Datei","Sinnvoll benannt, richtiger Ordner, erneut geöffnet."]],"why":"Erst der Test an der fertigen Datei zeigt, ob der Export gelungen ist.","start":74,"image":"dokumente-06.svg"},{"title":"Jetzt Ihr eigenes Dossier","kind":"path","seconds":12,"caption":"Wählen Sie Scanweg mit Papier oder Bildweg mit den drei Übungsbildern. Planen Sie die Reihenfolge in der Werkbank und erstellen Sie dann Ihre echte PDF.","cards":[["Planen","Material wählen, Reihenfolge begründen."],["Erstellen","3 Seiten in einer gemeinsamen PDF speichern."],["Nachweisen","Fundstellen, Dateiname und Dateigrösse im Check notieren."]],"why":"Der Dossier-Plan begleitet Ihre PDF; er ersetzt sie nicht.","start":88,"image":"dokumente-07.svg"}]},"faktencheck":{"title":"Echt oder Fake?","tag":"Ein Urteil, dessen Weg man nachvollziehen kann","duration":100,"chapters":[{"title":"Behauptung → Belege → Urteil","kind":"cards","seconds":12,"caption":"Beginnen Sie mit einem überprüfbaren Satz. Lesen Sie zwei brauchbare Quellen verschiedener Organisationen. Das Urteil darf nur so weit gehen wie die Belege.","cards":[["Behauptung","Was genau soll wahr sein?"],["Belege","Was steht tatsächlich in Quelle 1 und Quelle 2?"],["Urteil","Was folgt daraus – mit welcher Einschränkung?"]],"why":"Zwei verlinkte Suchtreffer sind noch keine nachvollziehbare Prüfung.","start":0,"image":"faktencheck-01.svg"},{"title":"Beispiel 1 · «Inkognito = unsichtbar»","kind":"evidence","seconds":16,"caption":"Google und Mozilla erklären: Privates Surfen beschränkt lokale Spuren, macht aber nicht anonym. Die genaue Funktionsweise hängt vom Browser ab. Die Quellen sind unter dem Video verlinkt.","cards":[["Google · Chrome-Hilfe","Websites und Netzwerkbetreiber können Aktivitäten möglicherweise beobachten."],["Mozilla · Firefox-Hilfe","Privater Modus macht im Internet nicht anonym."],["Begründetes Urteil","Die pauschale Behauptung ist falsch: weniger lokale Spuren bedeutet nicht unsichtbar."]],"why":"Die Begründung nennt beide Belege und unterscheidet lokal von online.","start":12,"image":"faktencheck-02.svg"},{"title":"Beispiel 2 · Was bleibt gespeichert?","kind":"compare","seconds":16,"caption":"Die Aussage «Im privaten Modus wird alles gelöscht» ist zu pauschal. Laut Google und Mozilla bleiben heruntergeladene Dateien erhalten. Prüfen Sie die beschriebenen Browser getrennt.","cards":[["Behauptung","«Nach dem Schliessen ist alles weg.»"],["Passender Beleg","Heruntergeladene Dateien bleiben auf dem Gerät."],["Genauer formuliert","Lokale Surfspuren werden eingeschränkt; Downloads verschwinden dadurch nicht."]],"why":"Wörter wie «alles» und «niemand» verlangen besonders genaue Belege.","start":28,"image":"faktencheck-03.svg"},{"title":"Beispiel 3 · Ein Bild ohne Kontext","kind":"evidence","seconds":16,"caption":"Erfundener Übungsfall: Ein Post behauptet, ein Bild sei von heute. Ein Vereinsarchiv zeigt dasselbe Motiv mit älterem Datum. Ohne geklärten Ursprung bleibt der aktuelle Zeitpunkt unbewiesen.","cards":[["Post · Übungsfall","«Dieses Foto zeigt den heutigen Anlass.»"],["Archiv · Übungsfall","Dasselbe Motiv erscheint mit einem älteren Datum."],["Vorsichtiges Urteil","«Von heute» ist nicht ausreichend belegt. Den Ursprung des Fotos weiter prüfen."]],"why":"Ein offenes Urteil ist besser als eine Sicherheit, die Ihre Belege nicht tragen.","start":44,"image":"faktencheck-04.svg"},{"title":"Eine Quelle so festhalten, dass sie prüfbar ist","kind":"cards","seconds":14,"caption":"Notieren Sie Organisation, Seitentitel, vollständigen Link, Abschnitt und Abrufdatum. Schreiben Sie den Beleg in eigenen Worten und nennen Sie seine Grenze.","cards":[["Fundort","Google Chrome-Hilfe · Inkognitomodus\nAbschnitt: Was auf dem Gerät gespeichert wird"],["Beleg","Downloads bleiben nach Ende der Sitzung erhalten."],["Grenze","Diese Quelle erklärt Chrome. Nicht ungeprüft auf alle Programme übertragen."]],"why":"Eine andere Person kann Ihren Beleg gezielt wiederfinden.","start":60,"image":"faktencheck-05.svg"},{"title":"Klar gestalten, ehrlich urteilen","kind":"board","seconds":14,"caption":"Eine gute Faktencheck-Karte trennt Behauptung, Belege, Urteil und Quellen. Die Quellenlinks und die Einschränkung bleiben auch in einer kurzen Fassung sichtbar.","cards":[["Behauptung","Ein genauer Satz."],["Belege","Quelle 1 und Quelle 2 gegenüberstellen."],["Urteil","Stimmt / teilweise / falsch / offen – begründet."],["Quellen","Beide Links, Fundstellen und Abrufdaten."]],"why":"Die Gestaltung macht Ihren Gedankengang überprüfbar.","start":74,"image":"faktencheck-06.svg"},{"title":"Jetzt Ihre eigene Prüfung","kind":"path","seconds":12,"caption":"Wählen Sie eine Vorlage. Lesen Sie die Quellen selbst, auch wenn Sie das Beispielvideo kennen. Verknüpfen Sie Ihr Urteil mit den tatsächlich gelesenen Belegen.","cards":[["Eingrenzen","Eine Aussage und eine genaue Prüffrage."],["Lesen","Zwei Organisationen, passende Fundstellen."],["Begründen","Eigenes Urteil mit einer ehrlichen Einschränkung."]],"why":"Das Beispiel zeigt die Methode. Ihre Arbeit zeigt Ihre eigene Prüfung.","start":88,"image":"faktencheck-07.svg"}]},"lifehacks":{"title":"Fünf Tricks, die bleiben","tag":"Kleine Handgriffe. Sichtbar getestet.","duration":108,"chapters":[{"title":"Ein Tipp braucht einen Beweis","kind":"cards","seconds":12,"caption":"Eine gute Tippkarte verbindet Nutzen, zwei bis drei Schritte, eigenen Test und eine Grenze. Ein hübsches Symbol allein zeigt noch keinen Test.","cards":[["Hilft, wenn …","Ich eine bestimmte Information suche."],["So geht es","Programm nennen, Handlung kurz erklären."],["Mein Test","Sichtbares Ergebnis zeigen und eine Grenze nennen."]],"why":"Ihre Sammlung soll anderen beim Ausprobieren helfen.","start":0,"image":"lifehacks-01.svg"},{"title":"Tipp 1 · Auf einer Seite suchen","kind":"browser","seconds":14,"caption":"Beispiel Chrome unter Windows: Strg und F öffnet die Suche auf der aktuellen Seite. Geben Sie einen vorhandenen Begriff ein und prüfen Sie den markierten Treffer.","cards":[["Tasten","Strg + F"],["Eigener Test","Im Übungstext «Abgabe» suchen. Der Treffer wird markiert."],["Grenze","Sucht auf der aktuellen Seite, nicht im ganzen Internet."]],"why":"Zeigen Sie im eigenen Bild den Suchbegriff und einen Treffer.","start":12,"image":"lifehacks-02.svg"},{"title":"Tipp 2 · Einen Tab zurückholen","kind":"browser","seconds":14,"caption":"Beispiel Chrome unter Windows: Öffnen und schliessen Sie eine harmlose Seite. Mit Strg, Umschalt und T öffnen Sie einen kürzlich geschlossenen Tab wieder.","cards":[["Tasten","Strg + Umschalt + T"],["Eigener Test","Eine Übungsseite schliessen und wieder öffnen."],["Grenze","Privat geschlossene Tabs werden auf diesem Weg nicht wiederhergestellt."]],"why":"Testen Sie an einer Seite ohne ungespeicherte Arbeit.","start":26,"image":"lifehacks-03.svg"},{"title":"Tipp 3 · Gezielt aufnehmen","kind":"browser","seconds":14,"caption":"Unter Windows öffnet Windows, Umschalt und S die Screenshot-Auswahl. Wählen Sie den wichtigen Bereich. Prüfen Sie das eingefügte Bild auf Lesbarkeit und private Angaben.","cards":[["Tasten","Windows + Umschalt + S"],["Eigener Test","Nur den relevanten Bereich aufnehmen und in die Tippkarte einfügen."],["Grenze","Zu kleine Ausschnitte können wichtige Zusammenhänge abschneiden."]],"why":"Ihr Bild zeigt die Information, die Ihre Erklärung braucht.","start":40,"image":"lifehacks-04.svg"},{"title":"Tipp 4 · Eine Aufgabe klar abhaken","kind":"board","seconds":14,"caption":"Erstellen Sie in OneNote eine echte Aufgabenmarkierung. Formulieren Sie ein sichtbares Ergebnis. Haken Sie erst ab, wenn Sie dieses Ergebnis geprüft haben.","cards":[["Aufgabe","PDF öffnen und alle 3 Seiten prüfen."],["Erster Schritt","Datei im Projektordner öffnen."],["Test","Aufgabe ausführen, Ergebnis kontrollieren, Kästchen abhaken."],["Grenze","Ein Kästchen löst keine automatische Erinnerung aus."]],"why":"Die Checkliste verbindet eine Handlung mit einer ehrlichen Kontrolle.","start":54,"image":"lifehacks-05.svg"},{"title":"Tipp 5 · PDF vor der Abgabe prüfen","kind":"pages","seconds":14,"caption":"Öffnen Sie die exportierte PDF als eigene Datei. Prüfen Sie Seitenzahl, Lesbarkeit und einen wichtigen Inhalt. So entdecken Sie Fehler, die im Arbeitsprogramm nicht auffielen.","cards":[["Anzahl","Sind alle erwarteten Seiten enthalten?"],["Lesbarkeit","Sind kleine Angaben und Ränder lesbar?"],["Inhalt","Finde ich eine vorher festgelegte Information?"]],"why":"Der Test untersucht das tatsächliche Produkt, das Sie abgeben.","start":68,"image":"lifehacks-06.svg"},{"title":"Von einem Versprechen zu einem Nutzen","kind":"compare","seconds":14,"caption":"Schreiben Sie, was bei Ihrem Test tatsächlich besser ging. Vermeiden Sie erfundene Zeitersparnisse. Prüfen Sie einen Tipp zusätzlich mit einer anderen Person.","cards":[["Zu ungenau","«Dieser Trick spart mega viel Zeit.»"],["Nachvollziehbar","«Ich finde den Abgabetermin direkt über den markierten Treffer.»"],["Test zu zweit","Die Person führt den Tipp nur mit Ihrer Karte aus."]],"why":"Eine konkrete Beobachtung ist überzeugender als ein grosses Versprechen.","start":82,"image":"lifehacks-07.svg"},{"title":"Jetzt Ihre fünf Tippkarten","kind":"path","seconds":12,"caption":"Wählen Sie fünf unterschiedliche Tricks. Mindestens zwei sollen für Sie noch keine Routine sein. Nutzen Sie eine Vorlage und ergänzen Sie eigene Tests, Bilder und Grenzen.","cards":[["Wählen","Fünf Tricks, die in Ihren Alltag passen."],["Testen","Eigener Versuch, sichtbares Ergebnis, eigene Darstellung."],["Verbessern","Eine Karte ohne Zusatzhilfe testen lassen."]],"why":"Ihr persönlicher Favorit bekommt eine Begründung, keine blosse Krone.","start":96,"image":"lifehacks-08.svg"}]}};
